package week_09.data_structures.class_problems;
public class LibraryCatalogLookup {static class Book{String isbn,title;Book(String i,String t){isbn=i;title=t;}}public static String findBook(Book[]catalog,String target){int low=0,high=catalog.length-1;while(low<=high){int mid=low+(high-low)/2;int cmp=catalog[mid].isbn.compareTo(target);if(cmp==0)return catalog[mid].title;if(cmp<0)low=mid+1;else high=mid-1;}return "Not Found";}public static void main(String[]args){Book[]books={new Book("000111","Algebra"),new Book("000222","Beginning Java"),new Book("000333","Data Structures")};System.out.println(findBook(books,"000222"));}}